+    }
+    if !cli.add_line.is_empty() {
+        settings.add_lines = cli.add_line.clone();
+    }
+    if let Some(color) = &cli.add_line_color {
+        settings.add_line_color = parse_color(color).unwrap_or(settings.add_line_color);
+    }
+    if let Some(range) = &cli.highlight_range {
+        settings.highlight_range = Some(parse_line_range(range)?);
+    }
+    settings.relative_highlight_range = cli.relative_highlight_range;
+    if let Some(color) = &cli.highlight_range_color {
+        settings.highlight_range_color = parse_color(color).unwrap_or(settings.highlight_range_color);
+    }
+    if let Some(raw) = &cli.raw_highlight_lines {
+        settings.raw_highlight_lines = parse_raw_highlight_lines(raw)?;
+    }
+    if let Some(value) = &cli.watermark {
+        settings.watermark = value.clone();
+    }
+    if let Some(value) = &cli.watermark_font_family {
+        settings.watermark_font_family = value.clone();
+    }
+    if let Some(color) = &cli.watermark_color {
+        settings.watermark_color = parse_color(color).unwrap_or(settings.watermark_color);
+    }
+    if let Some(radius) = cli.shadow_radius {
+        settings.shadow_radius = radius;
+    }
+    if let Some(color) = &cli.shadow_color {
+        settings.shadow_color = parse_color(color).unwrap_or(settings.shadow_color);
+    }
+    if let Some(value) = cli.mac_window_bar {
+        settings.mac_window_bar = value;
+    }
+    if cli.has_border {
+        settings.has_border = true;
+    }
+    if let Some(color) = &cli.border_color {
+        settings.border_color = parse_color(color).unwrap_or(settings.border_color);
+    }
+    if let Some(value) = cli.margin_x {
+        settings.margin_x = value;
+    }
+    if let Some(value) = cli.margin_y {
+        settings.margin_y = value;
+    }
+    if let Some(value) = &cli.title {
+        settings.title = Some(value.clone());
+    }
+    if let Some(value) = &cli.title_font_family {
+        settings.title_font_family = value.clone();
+    }
+    if let Some(color) = &cli.title_color {
+        settings.title_color = parse_color(color).unwrap_or(settings.title_color);
+    }
+    if let Some(background) = &cli.background {
+        apply_background_override(settings, background);
+    }
+
+    Ok(())
+}
+
+fn apply_background_override(settings: &mut AppSettings, value: &str) {
+    if let Some((left, right)) = value.split_once("->") {
+        if let Some(color) = parse_color(left.trim()) {
+            settings.background_start = color;
+        }
+        if let Some(color) = parse_color(right.trim()) {
+            settings.background_end = color;
+        }
+        return;
+    }
+    if let Some((left, right)) = value.split_once(',') {
+        if let Some(color) = parse_color(left.trim()) {
+            settings.background_start = color;
+        }
+        if let Some(color) = parse_color(right.trim()) {
+            settings.background_end = color;
+        }
+        return;
+    }
+    if let Some(color) = parse_color(value) {
+        settings.background_start = color;
+        settings.background_end = color;
+    }
+}
+
+fn build_input(cli: &Cli) -> Result<InputData> {
+    if let Some(from_file) = &cli.from_file {
+        let bytes = fs::read(from_file).with_context(|| format!("failed to read {}", from_file.display()))?;
+        let content = String::from_utf8_lossy(&bytes).into_owned();
+        return Ok(InputData::Text(build_text_input(
+            &content,
+            cli.language.clone().unwrap_or_else(|| detect_language(from_file, cli.file_path.as_deref())),
+            Some(from_file.display().to_string()),
+            cli,
+            false,
+        )?));
+    }
+
+    if let Some(code) = &cli.from_code {
+        return Ok(InputData::Text(build_text_input(
+            code,
+            cli.language
+                .clone()
+                .unwrap_or_else(|| detect_language(Path::new(""), cli.file_path.as_deref())),
+            cli.file_path.clone(),
+            cli,
+            false,
+        )?));
+    }
+
+    if let Some(from_image) = &cli.from_image {
+        if from_image.is_empty() {
+            bail!(CLIPBOARD_ERROR);
+        }
+        let image_path = PathBuf::from(from_image);
+        let image = image::open(&image_path)
+            .with_context(|| format!("failed to read {}", image_path.display()))?
+            .to_rgba8();
+        return Ok(InputData::Image(image));
+    }
+
+    if cli.from_clipboard {
+        bail!(CLIPBOARD_ERROR);
+    }
+
+    if !cli.execute.is_empty() {
+        let mut lines = Vec::new();
+        for command_text in &cli.execute {
+            lines.push(prompt_line(command_text));
+            if cli.skip {
+                lines.push(String::new());
+                continue;
+            }
+            let output = Command::new("sh").arg("-c").arg(command_text).output();
+            match output {
+                Ok(result) => {
+                    let mut rendered = String::new();
+                    rendered.push_str(&String::from_utf8_lossy(&result.stdout));
+                    rendered.push_str(&String::from_utf8_lossy(&result.stderr));
+                    let rendered = rendered.replace('\r', "");
+                    if rendered.is_empty() {
+                        continue;
+                    }
+                    lines.extend(rendered.split('\n').map(ToOwned::to_owned));
+                    if lines.last().is_some_and(String::is_empty) {
+                        lines.pop();
+                    }
+                }
+                Err(err) => lines.push(err.to_string()),
+            }
+        }
+        return Ok(InputData::Text(build_text_input_from_lines(
+            lines,
+            "shell".to_string(),
+            cli,
+            true,
+        )?));
+    }
+
+    bail!("No code snippet provided");
+}
+
+fn build_text_input(
+    content: &str,
+    language: String,
+    breadcrumbs_path: Option<String>,
+    cli: &Cli,
+    shell_mode: bool,
+) -> Result<TextInput> {
+    let lines = content.replace('\r', "");
+    let lines: Vec<String> = lines.split('\n').map(ToOwned::to_owned).collect();
+    build_text_input_from_lines_with_path(lines, language, breadcrumbs_path, cli, shell_mode)
+}
+
+fn build_text_input_from_lines(
+    lines: Vec<String>,
+    language: String,
+    cli: &Cli,
+    shell_mode: bool,
+) -> Result<TextInput> {
+    build_text_input_from_lines_with_path(lines, language, cli.file_path.clone(), cli, shell_mode)
+}
+
+fn build_text_input_from_lines_with_path(
+    mut lines: Vec<String>,
+    language: String,
+    breadcrumbs_path: Option<String>,
+    cli: &Cli,
+    shell_mode: bool,
+) -> Result<TextInput> {
+    let mut range_start = 1;
+    if let Some(range) = &cli.range {
+        let parsed = parse_line_range(range)?;
+        let (selected, start_index) = apply_line_range(lines, parsed);
+        lines = selected;
+        range_start = start_index;
+    }
+    if lines.is_empty() {
+        lines.push(String::new());
+    }
+    Ok(TextInput {
+        lines,
+        language,
+        breadcrumbs_path,
+        range_start,
+        shell_mode,
+    })
+}
+
+fn build_render_request(input: TextInput, settings: &AppSettings) -> Result<RenderRequest> {
+    let breadcrumbs = if settings.has_breadcrumbs {
+        input
+            .breadcrumbs_path
+            .as_ref()
+            .map(|path| path.replace('/', &settings.breadcrumbs_separator))
+    } else {
+        None
+    };
+
+    let line_number_start = settings
+        .start_line_number
+        .unwrap_or(input.range_start);
+
+    let mut lines = Vec::with_capacity(input.lines.len());
+    for (idx, line) in input.lines.iter().enumerate() {
+        let visible_line_number = idx + 1;
+        let absolute_line_number = input.range_start + idx;
+        let highlight = compute_highlight_color(
+            visible_line_number,
+            absolute_line_number,
+            settings,
+        );
+        let segments = if input.shell_mode {
+            if let Some(rest) = line.strip_prefix("> ") {
+                highlight_shell_line(rest)
+            } else {
+                vec![Segment {
+                    text: line.clone(),
+                    color: Color::opaque(144, 149, 164),
+                }]
+            }
+        } else {
+            highlight_code_line(line, &input.language)
+        };
+        lines.push(RenderLine { segments, highlight });
+    }
+
+    Ok(RenderRequest {
+        lines,
+        breadcrumbs,
+        line_number_start,
+    })
+}
+
+fn determine_output_mode(output: &str) -> Result<OutputMode> {
+    if output == "clipboard" {
+        return Ok(OutputMode::Clipboard);
+    }
+    let path = PathBuf::from(output);
+    let ext = path
+        .extension()
+        .and_then(|value| value.to_str())
+        .map(|value| value.to_ascii_lowercase());
+    match ext.as_deref() {
+        Some("png") => Ok(OutputMode::FilePng(path)),
+        Some("svg") => Ok(OutputMode::FileSvg(path)),
+        _ => bail!("Unsupported output format"),
+    }
+}
+
+fn write_image_output(
+    output_mode: OutputMode,
+    image: RgbaImage,
+    output_display: &str,
+    silent: bool,
+) -> Result<()> {
+    match output_mode {
+        OutputMode::Clipboard => bail!(CLIPBOARD_ERROR),
+        OutputMode::FilePng(path) => {
+            if let Some(parent) = path.parent() {
+                if !parent.as_os_str().is_empty() {
+                    fs::create_dir_all(parent)
+                        .with_context(|| format!("failed to create {}", parent.display()))?;
+                }
+            }
+            image.save(&path).with_context(|| format!("failed to write {}", path.display()))?;
+        }
+        OutputMode::FileSvg(path) => {
+            if let Some(parent) = path.parent() {
+                if !parent.as_os_str().is_empty() {
+                    fs::create_dir_all(parent)
+                        .with_context(|| format!("failed to create {}", parent.display()))?;
+                }
+            }
+            let mut png_bytes = Vec::new();
+            encode_png(&image, &mut png_bytes)?;
+            let encoded = base64::engine::general_purpose::STANDARD.encode(png_bytes);
+            let svg = format!(
+                "<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{encoded}\"/></svg>"
+            );
+            fs::write(&path, svg).with_context(|| format!("failed to write {}", path.display()))?;
+        }
+    }
+
+    if !silent {
+        success(&format!("Snapshot saved to {output_display} successful!"));
+    }
+    Ok(())
+}
+
+fn encode_png(image: &RgbaImage, output: &mut Vec<u8>) -> Result<()> {
+    let encoder = PngEncoder::new(Cursor::new(output));
+    encoder
+        .write_image(
+            image.as_raw(),
+            image.width(),
+            image.height(),
+            ColorType::Rgba8.into(),
+        )
+        .context("failed to encode png")
+}
+
+fn render_snapshot(request: &RenderRequest, settings: &AppSettings) -> Result<RgbaImage> {
+    let fonts = load_fonts()?;
+    let scale = settings.scale_factor.max(1.0);
+
+    let code_font_size = 17.0 * scale;
+    let code_font = fonts.code.as_scaled(PxScale::from(code_font_size));
+    let line_height = 18.0 * scale;
+    let title_font_size = 15.0 * scale;
+    let title_font = fonts.sans_bold.as_scaled(PxScale::from(title_font_size));
+    let watermark_font_size = 33.0 * scale;
+    let watermark_font = fonts.sans_bold.as_scaled(PxScale::from(watermark_font_size));
+    let breadcrumb_font_size = 15.0 * scale;
+    let breadcrumb_font = fonts.code.as_scaled(PxScale::from(breadcrumb_font_size));
+    let line_number_font = fonts.code.as_scaled(PxScale::from(code_font_size));
+
+    let window_padding_x = (14.0 * scale) as u32;
+    let content_left_padding = (16.0 * scale) as u32;
+    let window_top = (66.0 * scale) as u32;
+    let window_left = (64.0 * scale) as u32;
+    let window_min_width = (390.0 * scale) as u32;
+    let window_rounding = (12.0 * scale) as i32;
+    let top_bar_height = 32.0 * scale;
+    let content_offset = 24.0 * scale;
+    let breadcrumb_offset = if request.breadcrumbs.is_some() {
+        15.0 * scale
+    } else {
+        0.0
+    };
+    let window_height = ((82.0 + request.lines.len() as f32 * 18.0) * scale + breadcrumb_offset) as u32;
+    let image_height = ((290.0 + request.lines.len() as f32 * 18.0) * scale + breadcrumb_offset) as u32;
+
+    let line_number_digits = if settings.has_line_number {
+        let last = request.line_number_start + request.lines.len().saturating_sub(1);
+        last.to_string().len().max(1)
+    } else {
+        0
+    };
+    let line_number_gutter = if settings.has_line_number {
+        let sample = "8".repeat(line_number_digits);
+        text_width(&line_number_font, &sample) + (10.0 * scale)
+    } else {
+        0.0
+    };
+
+    let content_width = request
+        .lines
+        .iter()
+        .map(|line| {
+            line.segments
+                .iter()
+                .map(|segment| text_width(&code_font, &segment.text))
+                .sum::<f32>()
+        })
+        .fold(0.0, f32::max);
+
+    let breadcrumb_width = request
+        .breadcrumbs
+        .as_ref()
+        .map(|value| text_width(&breadcrumb_font, value))
+        .unwrap_or(0.0);
+
+    let title_width = settings
+        .title
+        .as_ref()
+        .map(|value| text_width(&title_font, value))
+        .unwrap_or(0.0);
+
+    let needed_width = content_width
+        + line_number_gutter
+        + (content_left_padding as f32 * 2.0)
+        + (window_padding_x as f32 * 2.0)
+        + 8.0 * scale
+        + breadcrumb_width.max(title_width).min(0.0);
+    let window_width = window_min_width.max(needed_width.ceil() as u32);
+    let image_width = window_width + window_left * 2;
+
+    let mut image = RgbaImage::new(image_width, image_height);
+    draw_gradient_background(&mut image, settings.background_start, settings.background_end);
+
+    let shadow_layers = settings.shadow_radius.max(1).min(24);
+    for idx in 0..shadow_layers {
+        let alpha = ((settings.shadow_color.a as f32) * (1.0 - idx as f32 / shadow_layers as f32) * 0.4) as u8;
+        let inflate = idx as i32 * (scale.round() as i32).max(1);
+        let shadow_rect = Rect::at(window_left as i32 - inflate / 2, window_top as i32 - inflate / 3)
+            .of_size(window_width + inflate as u32, window_height + inflate as u32);
+        fill_rounded_rect(
+            &mut image,
+            shadow_rect,
+            window_rounding + inflate / 2,
+            Color::new(
+                settings.shadow_color.r,
+                settings.shadow_color.g,
+                settings.shadow_color.b,
+                alpha,
+            )
+            .rgba(),
+        );
+    }
+
+    if settings.has_border {
+        fill_rounded_rect(
+            &mut image,
+            Rect::at(window_left as i32, window_top as i32).of_size(window_width, window_height),
+            window_rounding,
+            settings.border_color.rgba(),
+        );
+        fill_rounded_rect(
+            &mut image,
+            Rect::at(window_left as i32 + 2, window_top as i32 + 2)
+                .of_size(window_width.saturating_sub(4), window_height.saturating_sub(4)),
+            (window_rounding - 2).max(1),
+            Color::opaque(37, 41, 58).rgba(),
+        );
+    } else {
+        fill_rounded_rect(
+            &mut image,
+            Rect::at(window_left as i32, window_top as i32).of_size(window_width, window_height),
+            window_rounding,
+            Color::opaque(37, 41, 58).rgba(),
+        );
+    }
+
+    if settings.mac_window_bar {
+        let traffic_y = window_top as i32 + (18.0 * scale) as i32;
+        let red_x = window_left as i32 + (16.0 * scale) as i32;
+        let gap = (13.0 * scale) as i32;
+        let radius = (5.0 * scale) as i32;
+        draw_filled_circle_mut(&mut image, (red_x, traffic_y), radius, Color::opaque(255, 98, 87).rgba());
+        draw_filled_circle_mut(
+            &mut image,
+            (red_x + gap, traffic_y),
+            radius,
+            Color::opaque(255, 189, 46).rgba(),
+        );
+        draw_filled_circle_mut(
+            &mut image,
+            (red_x + gap * 2, traffic_y),
+            radius,
+            Color::opaque(40, 201, 64).rgba(),
+        );
+    }
+
+    if let Some(title) = &settings.title {
+        let title_width = text_width(&title_font, title);
+        let title_x = window_left as f32 + (window_width as f32 - title_width) / 2.0;
+        let title_y = window_top as f32 + 8.0 * scale;
+        draw_text_mut(
+            &mut image,
+            settings.title_color.rgba(),
+            title_x.round() as i32,
+            title_y.round() as i32,
+            PxScale::from(title_font_size),
+            &fonts.sans_bold,
+            title,
+        );
+    }
+
+    let breadcrumb_y = window_top as f32 + top_bar_height + 4.0 * scale;
+    if let Some(breadcrumbs) = &request.breadcrumbs {
+        draw_text_mut(
+            &mut image,
+            settings.breadcrumbs_color.rgba(),
+            (window_left + content_left_padding) as i32,
+            breadcrumb_y.round() as i32,
+            PxScale::from(breadcrumb_font_size),
+            &fonts.code,
+            breadcrumbs,
+        );
+    }
+
+    let content_start_y = window_top as f32 + top_bar_height + content_offset + breadcrumb_offset;
+    for (idx, line) in request.lines.iter().enumerate() {
+        let line_y = content_start_y + idx as f32 * line_height;
+
+        if let Some(highlight) = line.highlight {
+            let rect_y = line_y as i32 - (4.0 * scale) as i32;
+            let rect_h = (16.0 * scale) as u32;
+            draw_filled_rect_mut(
+                &mut image,
+                Rect::at(window_left as i32 + 1, rect_y)
+                    .of_size(window_width.saturating_sub(2), rect_h),
+                highlight.rgba(),
+            );
+        }
+
+        if settings.has_line_number {
+            let number = (request.line_number_start + idx).to_string();
+            let number_x = window_left as f32 + content_left_padding as f32;
+            draw_text_mut(
+                &mut image,
+                settings.line_number_color.rgba(),
+                number_x.round() as i32,
+                line_y.round() as i32,
+                PxScale::from(code_font_size),
+                &fonts.code,
+                &number,
+            );
+        }
+
+        let mut cursor_x =
+            window_left as f32 + content_left_padding as f32 + line_number_gutter as f32;
+        for segment in &line.segments {
+            draw_text_mut(
+                &mut image,
+                segment.color.rgba(),
+                cursor_x.round() as i32,
+                line_y.round() as i32,
+                PxScale::from(code_font_size),
+                &fonts.code,
+                &segment.text,
+            );
+            cursor_x += text_width(&code_font, &segment.text);
+        }
+    }
+
+    let watermark_y = window_top as f32 + window_height as f32 + 48.0 * scale;
+    let watermark_width = text_width(&watermark_font, &settings.watermark);
+    let watermark_x = (image_width as f32 - watermark_width) / 2.0;
+    draw_text_mut(
+        &mut image,
+        settings.watermark_color.rgba(),
+        watermark_x.round() as i32,
+        watermark_y.round() as i32,
+        PxScale::from(watermark_font_size),
+        &fonts.sans_bold,
+        &settings.watermark,
+    );
+
+    Ok(image)
+}
+
+fn draw_gradient_background(image: &mut RgbaImage, start: Color, end: Color) {
+    let width = image.width().max(1);
+    for x in 0..width {
+        let t = x as f32 / (width - 1).max(1) as f32;
+        let color = Color::new(
+            lerp(start.r, end.r, t),
+            lerp(start.g, end.g, t),
+            lerp(start.b, end.b, t),
+            255,
+        )
+        .rgba();
+        for y in 0..image.height() {
+            image.put_pixel(x, y, color);
+        }
+    }
+}
+
+fn fill_rounded_rect(image: &mut RgbaImage, rect: Rect, radius: i32, color: Rgba<u8>) {
+    let radius = radius.max(1) as u32;
+    let x = rect.left();
+    let y = rect.top();
+    let w = rect.width();
+    let h = rect.height();
+    if w <= radius * 2 || h <= radius * 2 {
+        draw_filled_rect_mut(image, rect, color);
+        return;
+    }
+
+    draw_filled_rect_mut(
+        image,
+        Rect::at(x + radius as i32, y).of_size(w - radius * 2, h),
+        color,
+    );
+    draw_filled_rect_mut(
+        image,
+        Rect::at(x, y + radius as i32).of_size(w, h - radius * 2),
+        color,
+    );
+
+    let tl = (x + radius as i32, y + radius as i32);
+    let tr = (x + w as i32 - radius as i32 - 1, y + radius as i32);
+    let bl = (x + radius as i32, y + h as i32 - radius as i32 - 1);
+    let br = (
+        x + w as i32 - radius as i32 - 1,
+        y + h as i32 - radius as i32 - 1,
+    );
+    draw_filled_circle_mut(image, tl, radius as i32, color);
+    draw_filled_circle_mut(image, tr, radius as i32, color);
+    draw_filled_circle_mut(image, bl, radius as i32, color);
+    draw_filled_circle_mut(image, br, radius as i32, color);
+}
+
+fn compute_highlight_color(
+    visible_line_number: usize,
+    absolute_line_number: usize,
+    settings: &AppSettings,
+) -> Option<Color> {
+    if settings.add_lines.contains(&absolute_line_number)
+        || settings.add_lines.contains(&visible_line_number)
+    {
+        return Some(settings.add_line_color);
+    }
+    if settings.delete_lines.contains(&absolute_line_number)
+        || settings.delete_lines.contains(&visible_line_number)
+    {
+        return Some(settings.delete_line_color);
+    }
+
+    if let Some(range) = settings.highlight_range {
+        let line_number = if settings.relative_highlight_range {
+            visible_line_number
+        } else {
+            absolute_line_number
+        };
+        let start = range.start.unwrap_or(1);
+        let end = range.end.unwrap_or(usize::MAX);
+        if (start..=end).contains(&line_number) {
+            return Some(settings.highlight_range_color);
+        }
+    }
+
+    for spec in &settings.raw_highlight_lines {
+        if (spec.start..=spec.end).contains(&visible_line_number)
+            || (spec.start..=spec.end).contains(&absolute_line_number)
+        {
+            return Some(spec.color);
+        }
+    }
+
+    None
+}
+
+fn parse_line_range(value: &str) -> Result<LineRange> {
+    let mut parts = value.splitn(2, ':');
+    let left = parts.next().unwrap_or_default();
+    let right = parts.next().unwrap_or_default();
+
+    if value.contains(':') {
+        let start = if left.is_empty() {
+            None
+        } else {
+            Some(left.parse::<usize>()?)
+        };
+        let end = if right.is_empty() {
+            None
+        } else {
+            Some(right.parse::<usize>()?)
+        };
+        Ok(LineRange { start, end })
+    } else {
+        let line = value.parse::<usize>()?;
+        Ok(LineRange {
+            start: Some(line),
+            end: Some(line),
+        })
+    }
+}
+
+fn apply_line_range(lines: Vec<String>, range: LineRange) -> (Vec<String>, usize) {
+    let start = range.start.unwrap_or(1).max(1);
+    let end = range.end.unwrap_or(lines.len()).min(lines.len());
+    if start > end || start > lines.len() {
+        return (Vec::new(), start);
+    }
+    let start_idx = start - 1;
+    let end_idx = end;
+    (lines[start_idx..end_idx].to_vec(), start)
+}
+
+fn parse_raw_highlight_lines(value: &str) -> Result<Vec<HighlightSpec>> {
+    let items: Vec<RawHighlightLine> = serde_json::from_str(value)?;
+    let mut result = Vec::new();
+    for RawHighlightLine(values) in items {
+        match values.as_slice() {
+            [line, color] => {
+                let line = line.as_u64().ok_or_else(|| anyhow!("invalid highlight line"))? as usize;
+                let color = color
+                    .as_str()
+                    .and_then(parse_color)
+                    .ok_or_else(|| anyhow!("invalid highlight color"))?;
+                result.push(HighlightSpec {
+                    start: line,
+                    end: line,
+                    color,
+                });
+            }
+            [start, end, color] => {
+                let start = start.as_u64().ok_or_else(|| anyhow!("invalid highlight line"))? as usize;
+                let end = end.as_u64().ok_or_else(|| anyhow!("invalid highlight line"))? as usize;
+                let color = color
+                    .as_str()
+                    .and_then(parse_color)
+                    .ok_or_else(|| anyhow!("invalid highlight color"))?;
+                result.push(HighlightSpec {
+                    start,
+                    end,
+                    color,
+                });
+            }
+            _ => bail!("invalid highlight line"),
+        }
+    }
+    Ok(result)
+}
+
+fn prompt_line(command_text: &str) -> String {
+    format!("> {command_text}")
+}
+
+fn highlight_shell_line(command_text: &str) -> Vec<Segment> {
+    if command_text.is_empty() {
+        return vec![
+            Segment {
+                text: "> ".to_string(),
+                color: Color::opaque(244, 143, 177),
+            },
+            Segment {
+                text: String::new(),
+                color: Color::opaque(255, 255, 255),
+            },
+        ];
+    }
+
+    let mut segments = vec![Segment {
+        text: "> ".to_string(),
+        color: Color::opaque(244, 143, 177),
+    }];
+    let mut parts = command_text.splitn(2, char::is_whitespace);
+    let command_name = parts.next().unwrap_or_default();
+    segments.push(Segment {
+        text: command_name.to_string(),
+        color: Color::opaque(167, 211, 128),
+    });
+    if let Some(rest) = parts.next() {
+        if !rest.is_empty() {
+            segments.push(Segment {
+                text: format!(" {rest}"),
+                color: Color::opaque(240, 240, 240),
+            });
+        }
+    }
+    segments
+}
+
+fn highlight_code_line(line: &str, language: &str) -> Vec<Segment> {
+    if line.trim().is_empty() {
+        return vec![Segment {
+            text: line.to_string(),
+            color: Color::opaque(240, 240, 240),
+        }];
+    }
+
+    let trimmed = line.trim_start();
+    if is_comment_line(trimmed, language) {
+        return vec![Segment {
+            text: line.to_string(),
+            color: Color::opaque(127, 132, 145),
+        }];
+    }
+
+    let chars: Vec<char> = line.chars().collect();
+    let mut segments = Vec::new();
+    let mut idx = 0;
+    let mut expecting_definition = false;
+
+    while idx < chars.len() {
+        let ch = chars[idx];
+        if ch.is_whitespace() {
+            let start = idx;
+            while idx < chars.len() && chars[idx].is_whitespace() {
+                idx += 1;
+            }
+            segments.push(Segment {
+                text: chars[start..idx].iter().collect(),
+                color: Color::opaque(240, 240, 240),
+            });
+            continue;
+        }
+
+        if matches!(ch, '"' | '\'' | '`') {
+            let start = idx;
+            let quote = ch;
+            idx += 1;
+            while idx < chars.len() {
+                let current = chars[idx];
+                idx += 1;
+                if current == '\\' && idx < chars.len() {
+                    idx += 1;
+                    continue;
+                }
+                if current == quote {
+                    break;
+                }
+            }
+            segments.push(Segment {
+                text: chars[start..idx].iter().collect(),
+                color: Color::opaque(233, 226, 138),
+            });
+            expecting_definition = false;
+            continue;
+        }
+
+        if ch.is_ascii_digit() {
+            let start = idx;
+            idx += 1;
+            while idx < chars.len()
+                && (chars[idx].is_ascii_alphanumeric() || matches!(chars[idx], '_' | '.'))
+            {
+                idx += 1;
+            }
+            segments.push(Segment {
+                text: chars[start..idx].iter().collect(),
+                color: Color::opaque(255, 184, 108),
+            });
+            expecting_definition = false;
+            continue;
+        }
+
+        if is_identifier_start(ch) {
+            let start = idx;
+            idx += 1;
+            while idx < chars.len() && is_identifier_continue(chars[idx]) {
+                idx += 1;
+            }
+            let token: String = chars[start..idx].iter().collect();
+            let next_non_ws = chars[idx..].iter().copied().find(|value| !value.is_whitespace());
+            let lowered = token.to_ascii_lowercase();
+            let color = if is_keyword(&lowered) {
+                expecting_definition = matches!(
+                    lowered.as_str(),
+                    "def" | "class" | "fn" | "function" | "struct" | "enum" | "trait"
+                );
+                Color::opaque(255, 143, 206)
+            } else if is_boolean(&lowered) {
+                expecting_definition = false;
+                Color::opaque(194, 154, 255)
+            } else if expecting_definition {
+                expecting_definition = false;
+                Color::opaque(98, 243, 146)
+            } else if next_non_ws == Some('(') {
+                expecting_definition = false;
+                Color::opaque(128, 216, 255)
+            } else {
+                expecting_definition = false;
+                Color::opaque(240, 240, 240)
+            };
+            segments.push(Segment { text: token, color });
+            continue;
+        }
+
+        segments.push(Segment {
+            text: ch.to_string(),
+            color: Color::opaque(240, 240, 240),
+        });
+        idx += 1;
+    }
+
+    segments
+}
+
+fn is_comment_line(line: &str, language: &str) -> bool {
+    let language = language.to_ascii_lowercase();
+    if language == "python" || language == "shell" || language == "bash" || language == "sh" {
+        return line.starts_with('#');
+    }
+    line.starts_with("//") || line.starts_with('#')
+}
+
+fn is_identifier_start(value: char) -> bool {
+    value == '_' || value.is_ascii_alphabetic()
+}
+
+fn is_identifier_continue(value: char) -> bool {
+    value == '_' || value.is_ascii_alphanumeric()
+}
+
+fn is_keyword(value: &str) -> bool {
+    matches!(
+        value,
+        "and"
+            | "as"
+            | "async"
+            | "await"
+            | "break"
+            | "case"
+            | "class"
+            | "const"
+            | "continue"
+            | "def"
+            | "default"
+            | "do"
+            | "elif"
+            | "else"
+            | "enum"
+            | "export"
+            | "extends"
+            | "finally"
+            | "fn"
+            | "for"
+            | "from"
+            | "function"
+            | "if"
+            | "impl"
+            | "import"
+            | "in"
+            | "interface"
+            | "let"
+            | "loop"
+            | "match"
+            | "mod"
+            | "mut"
+            | "package"
+            | "pass"
+            | "pub"
+            | "raise"
+            | "return"
+            | "static"
+            | "struct"
+            | "switch"
+            | "trait"
+            | "try"
+            | "type"
+            | "use"
+            | "var"
+            | "while"
+            | "with"
+            | "yield"
+    )
+}
+
+fn is_boolean(value: &str) -> bool {
+    matches!(value, "false" | "none" | "null" | "true")
+}
+
+fn detect_language(path: &Path, file_path_hint: Option<&str>) -> String {
+    let extension = path
+        .extension()
+        .and_then(|value| value.to_str())
+        .or_else(|| {
+            file_path_hint
+                .and_then(|value| Path::new(value).extension())
+                .and_then(|value| value.to_str())
+        })
+        .unwrap_or("")
+        .to_ascii_lowercase();
+
+    match extension.as_str() {
+        "bash" | "sh" | "zsh" => "shell".to_string(),
+        "c" | "h" => "c".to_string(),
+        "cpp" | "cc" | "cxx" | "hpp" => "cpp".to_string(),
+        "css" => "css".to_string(),
+        "go" => "go".to_string(),
+        "html" | "htm" => "html".to_string(),
+        "java" => "java".to_string(),
+        "js" | "jsx" => "javascript".to_string(),
+        "json" => "json".to_string(),
+        "php" => "php".to_string(),
+        "py" => "python".to_string(),
+        "rb" => "ruby".to_string(),
+        "rs" => "rust".to_string(),
+        "sql" => "sql".to_string(),
+        "swift" => "swift".to_string(),
+        "toml" => "toml".to_string(),
+        "ts" | "tsx" => "typescript".to_string(),
+        "yaml" | "yml" => "yaml".to_string(),
+        _ => "plain".to_string(),
+    }
+}
+
+fn parse_color(value: &str) -> Option<Color> {
+    let raw = value.trim().strip_prefix('#').unwrap_or(value.trim());
+    match raw.len() {
+        6 => {
+            let r = u8::from_str_radix(&raw[0..2], 16).ok()?;
+            let g = u8::from_str_radix(&raw[2..4], 16).ok()?;
+            let b = u8::from_str_radix(&raw[4..6], 16).ok()?;
+            Some(Color::opaque(r, g, b))
+        }
+        8 => {
+            let r = u8::from_str_radix(&raw[0..2], 16).ok()?;
+            let g = u8::from_str_radix(&raw[2..4], 16).ok()?;
+            let b = u8::from_str_radix(&raw[4..6], 16).ok()?;
+            let a = u8::from_str_radix(&raw[6..8], 16).ok()?;
+            Some(Color::new(r, g, b, a))
+        }
+        _ => None,
+    }
+}
+
+fn text_width(font: &impl ScaleFont<f32>, text: &str) -> f32 {
+    let mut width = 0.0;
+    for ch in text.chars() {
+        width += font.h_advance(font.glyph_id(ch));
+    }
+    width
+}
+
+fn lerp(start: u8, end: u8, t: f32) -> u8 {
+    (start as f32 + (end as f32 - start as f32) * t).round() as u8
+}
+
+fn info(message: &str) {
+    println!("\x1b[34m[INFO]\x1b[0m {message}");
+}
+
+fn warn(message: &str) {
+    println!("\x1b[33m[WARN]\x1b[0m {message}");
+}
+
+fn success(message: &str) {
+    println!("\x1b[32m[SUCCESS]\x1b[0m {message}");
+}
+
+#[derive(Clone)]
+struct LoadedFonts {
+    code: FontArc,
+    sans_bold: FontArc,
+}
+
+fn load_fonts() -> Result<LoadedFonts> {
+    let code = load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf")
+        .or_else(|_| load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"))?;
+    let sans_bold = load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf")
+        .or_else(|_| load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"))?;
+    Ok(LoadedFonts { code, sans_bold })
+}
+
+fn load_font_file(path: &str) -> Result<FontArc> {
+    let bytes = fs::read(path).with_context(|| format!("failed to read {path}"))?;
+    FontArc::try_from_vec(bytes).map_err(|_| anyhow!("failed to load font {path}"))
+}
+
+impl Color {
+    const fn new(r: u8, g: u8, b: u8, a: u8) -> Self {
+        Self { r, g, b, a }
+    }
+
+    const fn opaque(r: u8, g: u8, b: u8) -> Self {
+        Self { r, g, b, a: 255 }
+    }
+
+    fn rgba(self) -> Rgba<u8> {
+        Rgba([self.r, self.g, self.b, self.a])
+    }
+}
