use std::env;
use std::fs;
use std::io::Cursor;
use std::path::{Path, PathBuf};
use std::process::Command;

use ab_glyph::{Font, FontArc, PxScale, ScaleFont};
use anyhow::{anyhow, bail, Context, Result};
use base64::Engine;
use clap::{ArgAction, Parser};
use image::codecs::png::PngEncoder;
use image::{ColorType, GenericImageView, ImageEncoder, Rgba, RgbaImage};
use imageproc::drawing::{
    draw_filled_circle_mut, draw_filled_rect_mut, draw_hollow_circle_mut, draw_text_mut,
};
use imageproc::rect::Rect;
use serde::Deserialize;
use serde_json::Value;

const VERSION_OUTPUT: &str = "codesnap-cli 0.13.1";
const CLIPBOARD_ERROR: &str =
    "Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable";
const DEFAULT_CONFIG_JSON: &str = r#"{
  "print_eggs": false,
  "snapshot_config": {
    "theme": "candy",
    "window": {
      "mac_window_bar": true,
      "shadow": {
        "radius": 20,
        "color": "#00000040"
      },
      "margin": {
        "x": 82,
        "y": 82
      },
