fn is_boolean(value: &str) -> bool {
    matches!(value, "false" | "none" | "null" | "true")
}

fn detect_language(path: &Path, file_path_hint: Option<&str>) -> String {
    let extension = path
        .extension()
        .and_then(|value| value.to_str())
        .or_else(|| {
            file_path_hint
                .and_then(|value| Path::new(value).extension())
                .and_then(|value| value.to_str())
        })
        .unwrap_or("")
        .to_ascii_lowercase();

    match extension.as_str() {
        "bash" | "sh" | "zsh" => "shell".to_string(),
        "c" | "h" => "c".to_string(),
        "cpp" | "cc" | "cxx" | "hpp" => "cpp".to_string(),
        "css" => "css".to_string(),
        "go" => "go".to_string(),
        "html" | "htm" => "html".to_string(),
        "java" => "java".to_string(),
        "js" | "jsx" => "javascript".to_string(),
        "json" => "json".to_string(),
        "php" => "php".to_string(),
        "py" => "python".to_string(),
        "rb" => "ruby".to_string(),
        "rs" => "rust".to_string(),
        "sql" => "sql".to_string(),
        "swift" => "swift".to_string(),
        "toml" => "toml".to_string(),
        "ts" | "tsx" => "typescript".to_string(),
        "yaml" | "yml" => "yaml".to_string(),
        _ => "plain".to_string(),
    }
}

fn parse_color(value: &str) -> Option<Color> {
    let raw = value.trim().strip_prefix('#').unwrap_or(value.trim());
    match raw.len() {
        6 => {
            let r = u8::from_str_radix(&raw[0..2], 16).ok()?;
            let g = u8::from_str_radix(&raw[2..4], 16).ok()?;
            let b = u8::from_str_radix(&raw[4..6], 16).ok()?;
            Some(Color::opaque(r, g, b))
        }
        8 => {
            let r = u8::from_str_radix(&raw[0..2], 16).ok()?;
            let g = u8::from_str_radix(&raw[2..4], 16).ok()?;
            let b = u8::from_str_radix(&raw[4..6], 16).ok()?;
            let a = u8::from_str_radix(&raw[6..8], 16).ok()?;
            Some(Color::new(r, g, b, a))
        }
        _ => None,
    }
}

fn text_width(font: &impl ScaleFont<f32>, text: &str) -> f32 {
    let mut width = 0.0;
    for ch in text.chars() {
        width += font.h_advance(font.glyph_id(ch));
    }
    width
}

fn lerp(start: u8, end: u8, t: f32) -> u8 {
    (start as f32 + (end as f32 - start as f32) * t).round() as u8
}

fn info(message: &str) {
    println!("\x1b[34m[INFO]\x1b[0m {message}");
}

fn warn(message: &str) {
    println!("\x1b[33m[WARN]\x1b[0m {message}");
}

fn success(message: &str) {
    println!("\x1b[32m[SUCCESS]\x1b[0m {message}");
}

#[derive(Clone)]
struct LoadedFonts {
    code: FontArc,
    sans_bold: FontArc,
}

fn load_fonts() -> Result<LoadedFonts> {
    let code = load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf")
        .or_else(|_| load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"))?;
    let sans_bold = load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf")
        .or_else(|_| load_font_file("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"))?;
    Ok(LoadedFonts { code, sans_bold })
}

fn load_font_file(path: &str) -> Result<FontArc> {
    let bytes = fs::read(path).with_context(|| format!("failed to read {path}"))?;
    FontArc::try_from_vec(bytes).map_err(|_| anyhow!("failed to load font {path}"))
}

impl Color {
    const fn new(r: u8, g: u8, b: u8, a: u8) -> Self {
        Self { r, g, b, a }
    }

    const fn opaque(r: u8, g: u8, b: u8) -> Self {
        Self { r, g, b, a: 255 }
    }

    fn rgba(self) -> Rgba<u8> {
        Rgba([self.r, self.g, self.b, self.a])
    }
}

